-- E07-05B: immutable operator-declared contract references. NOT verification.
-- No documents, signatures or testing permissions are generated by this schema.
CREATE TABLE enkyron_crm_contract_references (
 id TEXT PRIMARY KEY,
 workspace_key TEXT NOT NULL,
 proposal_id TEXT NOT NULL,
 proposal_revision INTEGER NOT NULL CHECK(proposal_revision >= 1),
 sow_revision INTEGER NOT NULL CHECK(sow_revision >= 1),
 document_kind TEXT NOT NULL CHECK(document_kind IN
  ('nda','engagement_agreement','dpa','test_permission')),
 source_reference TEXT NOT NULL CHECK(length(btrim(source_reference)) BETWEEN 5 AND 300),
 source_sha256 CHAR(64) NOT NULL CHECK(source_sha256 ~ '^[a-f0-9]{64}$'),
 review_note TEXT NOT NULL CHECK(length(btrim(review_note)) BETWEEN 20 AND 500),
 evidence_status TEXT NOT NULL DEFAULT 'operator_reference_unverified'
  CHECK(evidence_status='operator_reference_unverified'),
 recorded_by TEXT NOT NULL,
 recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 CONSTRAINT enkyron_contract_ref_sow_fk
  FOREIGN KEY(workspace_key,proposal_id,proposal_revision,sow_revision)
  REFERENCES enkyron_crm_sow_draft_versions
   (workspace_key,proposal_id,proposal_revision,sow_revision) ON DELETE RESTRICT,
 CONSTRAINT enkyron_contract_ref_unique
  UNIQUE(workspace_key,proposal_id,proposal_revision,sow_revision,document_kind,source_sha256)
);
CREATE INDEX enkyron_contract_ref_history
 ON enkyron_crm_contract_references(workspace_key,proposal_id,proposal_revision DESC,recorded_at DESC,id DESC);
CREATE TRIGGER enkyron_contract_ref_immutable
 BEFORE UPDATE OR DELETE ON enkyron_crm_contract_references
 FOR EACH ROW EXECUTE FUNCTION enkyron_crm_events_immutable();
